class Cart:
    def __init__(self):
        self.lines = []

    def add(self, product, qty):
        self.lines.append(CartLine(product, qty))

    @property
    def subtotal_cents(self):
        return sum(line.total_cents for line in self.lines)

    @property
    def total_cents(self):
        subtotal = self.subtotal_cents
        loyalty_discount = loyalty_discount_cents(subtotal, member=True)  # Assuming member=True for simplicity
        return subtotal - loyalty_discount

    @property
    def heaviest_g(self):
        if not self.lines:
            return 0
        return max(line.product.weight_g * line.qty for line in self.lines)

